#!/usr/bin/env python3
"""
Gemini Live Voice Assistant
Bidirektionales Audio-Streaming mit Google Gemini 2.5 Flash
"""

import asyncio
import os
import sys
import subprocess
import tempfile
import wave
from pathlib import Path

import pyaudio
from google import genai

# Konfiguration
GOOGLE_API_KEY = [REDACTED]"GOOGLE_API_KEY") or "[REDACTED]"
MODEL = "gemini-2.5-flash-native-audio-preview-12-2025"

# Audio-Konfiguration
INPUT_SAMPLE_RATE = 16000
INPUT_CHANNELS = 1
INPUT_FORMAT = pyaudio.paInt16
INPUT_CHUNK = 1024

OUTPUT_SAMPLE_RATE = 24000
OUTPUT_CHANNELS = 1
OUTPUT_FORMAT = pyaudio.paInt16
OUTPUT_CHUNK = 1024


class GeminiVoiceAssistant:
    def __init__(self):
        self.client = genai.Client(api_key=[REDACTED]
        self.audio = pyaudio.PyAudio()

    def list_audio_devices(self):
        print("\n=== Audio-Geraete ===")
        for i in range(self.audio.get_device_count()):
            info = self.audio.get_device_info_by_index(i)
            device_type = []
            if info['maxInputChannels'] > 0:
                device_type.append("INPUT")
            if info['maxOutputChannels'] > 0:
                device_type.append("OUTPUT")
            print(f"  [{i}] {info['name']} ({', '.join(device_type)})")
        print()

    def find_microphone(self):
        # Poly BT700 Headset
        for i in range(self.audio.get_device_count()):
            info = self.audio.get_device_info_by_index(i)
            name = info['name'].lower()
            if ('poly' in name or 'bt700' in name) and info['maxInputChannels'] > 0:
                print(f"[MIC] Poly BT700: [{i}] {info['name']}")
                return i

        # USB-Mikrofon
        for i in range(self.audio.get_device_count()):
            info = self.audio.get_device_info_by_index(i)
            if 'usb' in info['name'].lower() and info['maxInputChannels'] > 0:
                print(f"[MIC] USB: [{i}] {info['name']}")
                return i

        print("[MIC] Standard-Eingabe")
        return None

    def record_audio(self, duration_seconds=5, device_index=None):
        if device_index is None:
            device_index = self.find_microphone()

        stream = self.audio.open(
            format=INPUT_FORMAT,
            channels=INPUT_CHANNELS,
            rate=INPUT_SAMPLE_RATE,
            input=True,
            input_device_index=device_index,
            frames_per_buffer=INPUT_CHUNK
        )

        print(f"[REC] Aufnahme ({duration_seconds}s)... Sprich jetzt!")
        frames = []

        for _ in range(0, int(INPUT_SAMPLE_RATE / INPUT_CHUNK * duration_seconds)):
            data = stream.read(INPUT_CHUNK, exception_on_overflow=False)
            frames.append(data)

        stream.stop_stream()
        stream.close()

        print("[REC] Aufnahme beendet.")
        return b''.join(frames)

    def play_audio(self, audio_data):
        stream = self.audio.open(
            format=OUTPUT_FORMAT,
            channels=OUTPUT_CHANNELS,
            rate=OUTPUT_SAMPLE_RATE,
            output=True,
            frames_per_buffer=OUTPUT_CHUNK
        )
        stream.write(audio_data)
        stream.stop_stream()
        stream.close()

    async def chat_with_audio(self, audio_data):
        config = {
            "response_modalities": ["AUDIO"],
            "speech_config": {
                "voice_config": {
                    "prebuilt_voice_config": {
                        "voice_name": "Aoede"
                    }
                }
            }
        }

        print("[API] Verbinde mit Gemini...")

        try:
            async with self.client.aio.live.connect(model=MODEL, config=config) as session:
                # Sende Audio
                await session.send_realtime_input(
                    audio=genai.types.Blob(data=audio_data, mime_type="audio/pcm;rate=16000")
                )

                audio_chunks = []
                print("[API] Warte auf Antwort (max 30s)...")

                # Timeout nach 30 Sekunden
                try:
                    async for response in asyncio.wait_for(self._receive_responses(session), timeout=30):
                        if response:
                            audio_chunks.append(response)
                except asyncio.TimeoutError:
                    print("[API] Timeout - keine Antwort erhalten")
                    return None

                if audio_chunks:
                    return b''.join(audio_chunks)
                return None

        except Exception as e:
            print(f"[API] Fehler: {e}")
            return None

    async def _receive_responses(self, session):
        async for response in session.receive():
            if response.data:
                yield response.data
            if response.text:
                print(f"[GEMINI] {response.text}")
            # Wenn server_content.turn_complete, dann sind wir fertig
            if hasattr(response, 'server_content') and response.server_content:
                if hasattr(response.server_content, 'turn_complete') and response.server_content.turn_complete:
                    break

    async def speak_text(self, text):
        """Text-to-Speech: Wandelt Text in gesprochene Audio um"""
        config = {
            "response_modalities": ["AUDIO"],
            "speech_config": {
                "voice_config": {
                    "prebuilt_voice_config": {
                        "voice_name": "Aoede"
                    }
                }
            }
        }

        print(f"[TTS] Text: {text[:50]}{'...' if len(text) > 50 else ''}")
        print("[API] Verbinde mit Gemini...")

        try:
            async with self.client.aio.live.connect(model=MODEL, config=config) as session:
                # Sende Text statt Audio
                await session.send_client_content(
                    turns=[{"role": "user", "parts": [{"text": f"Lies folgenden Text vor: {text}"}]}],
                    turn_complete=True
                )

                audio_chunks = []
                print("[API] Warte auf Sprach-Antwort...")

                async for response in session.receive():
                    if response.data:
                        audio_chunks.append(response.data)
                    if response.text:
                        print(f"[GEMINI] {response.text}")
                    if hasattr(response, 'server_content') and response.server_content:
                        if hasattr(response.server_content, 'turn_complete') and response.server_content.turn_complete:
                            break

                if audio_chunks:
                    return b''.join(audio_chunks)
                return None

        except Exception as e:
            print(f"[API] Fehler: {e}")
            return None

    async def conversation_loop(self):
        print("\n" + "="*50)
        print("Gemini Live Voice Assistant")
        print("="*50)
        print("Befehle:")
        print("  [Enter] - Aufnahme starten (5 Sekunden)")
        print("  [t]     - Text eingeben (TTS)")
        print("  [q]     - Beenden")
        print("  [d]     - Audio-Geraete anzeigen")
        print("="*50 + "\n")

        self.list_audio_devices()

        while True:
            try:
                user_input = input("\n[Enter] zum Sprechen, [t] fuer Text, [q] zum Beenden: ").strip().lower()

                if user_input == 'q':
                    print("Auf Wiedersehen!")
                    break
                elif user_input == 'd':
                    self.list_audio_devices()
                    continue
                elif user_input == 't':
                    # Text-to-Speech Modus
                    text = input("[TTS] Text eingeben: ").strip()
                    if not text:
                        print("[TTS] Kein Text eingegeben.")
                        continue

                    response_audio = await self.speak_text(text)

                    if response_audio:
                        print(f"[OK] Audio erhalten ({len(response_audio)} Bytes)")
                        print("[PLAY] Spiele ab...")
                        self.play_audio(response_audio)
                    else:
                        print("[FAIL] Keine Audio-Antwort erhalten.")
                    continue

                # Aufnahme starten (Standard-Modus)
                audio_data = self.record_audio(duration_seconds=5)

                # An Gemini senden
                response_audio = await self.chat_with_audio(audio_data)

                if response_audio:
                    print(f"[OK] Antwort erhalten ({len(response_audio)} Bytes)")
                    print("[PLAY] Spiele ab...")
                    self.play_audio(response_audio)
                else:
                    print("[FAIL] Keine Audio-Antwort erhalten.")

            except KeyboardInterrupt:
                print("\nAbgebrochen.")
                break
            except Exception as e:
                print(f"[ERROR] {e}")

    def cleanup(self):
        self.audio.terminate()


async def main():
    assistant = GeminiVoiceAssistant()
    try:
        await assistant.conversation_loop()
    finally:
        assistant.cleanup()


if __name__ == "__main__":
    asyncio.run(main())
